create function public.save_record(p_project uuid,p_table text,p_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$ <<save_record>> declare id uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid()); rec jsonb; c text; who uuid:=auth.uid(); kind text; n bigint; source uuid; sum_claim bigint:=0; item jsonb; begin
if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if;
perform 1 from public.projects where projects.id=p_project and (status in ('active','paused','closing') or (status='closed' and p_table='bills' and private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) and length(coalesce(p_data->>'notes',''))>=5 and exists(select 1 from public.financial_events where financial_events.id=(p_data->>'corrects_event_id')::uuid and project_id=p_project and event_type='BILL' and status='REVERSED'))) for update; if not found then raise exception 'PROJECT_CLOSED'; end if;
select currency into c from public.projects where projects.id=p_project;
if p_table not in ('bills','purchase_requests','advances','reimbursement_claims','comments','documents') then perform private.assert_finance(p_project); end if;
if p_data->>'id' is not null then
if p_table not in ('bills','purchase_requests','advances') then raise exception 'EDIT_NOT_SUPPORTED'; end if;
execute format('select to_jsonb(t) from public.%I t where id=$1 and project_id=$2 for update',p_table) into rec using id,p_project;
if rec is null or rec->>'status' not in ('draft','needs_info') then raise exception 'DRAFT_REQUIRED'; end if;
if coalesce((rec->>'created_by')::uuid,(rec->>'requester_user_id')::uuid)<>who and not private.finance(p_project) then raise exception 'PERMISSION_DENIED'; end if;
if p_table='bills' then delete from public.bill_items where bill_id=save_record.id;
elsif p_table='purchase_requests' then delete from public.purchase_request_items where request_id=save_record.id;
end if;
end if;
case p_table
when 'vendors' then insert into public.vendors(id,project_id,name,gstin,email,phone,address,notes) values(id,p_project,p_data->>'name',p_data->>'gstin',p_data->>'email',p_data->>'phone',p_data->>'address',p_data->>'notes');
when 'funding_sources' then insert into public.funding_sources(id,project_id,name,type,sanctioned_amount_minor,currency,notes) values(id,p_project,p_data->>'name',coalesce(p_data->>'type','other'),(p_data->>'sanctioned_amount_minor')::bigint,c,p_data->>'notes');
when 'financial_accounts' then if p_data->>'account_type' not in ('CASH','BANK','WALLET') then raise exception 'INVALID_ACCOUNT'; end if; insert into public.financial_accounts(id,project_id,name,account_type,currency) values(id,p_project,p_data->>'name',p_data->>'account_type',c);
when 'categories' then insert into public.categories(id,project_id,name) values(id,p_project,p_data->>'name');
when 'tags' then insert into public.tags(id,project_id,name) values(id,p_project,p_data->>'name');
when 'bills' then n:=(p_data->>'total_minor')::bigint; insert into public.bills(id,project_id,vendor_id,invoice_number,issue_date,due_date,subtotal_minor,tax_minor,total_minor,currency,category_id,linked_request_id,corrects_event_id,notes,created_by) values(id,p_project,(p_data->>'vendor_id')::uuid,p_data->>'invoice_number',coalesce((p_data->>'date')::date,current_date),(p_data->>'due_date')::date,n-coalesce((p_data->>'tax_minor')::bigint,0),coalesce((p_data->>'tax_minor')::bigint,0),n,c,(p_data->>'category_id')::uuid,(p_data->>'linked_request_id')::uuid,(p_data->>'corrects_event_id')::uuid,p_data->>'notes',who) on conflict on constraint bills_pkey do update set vendor_id=excluded.vendor_id,invoice_number=excluded.invoice_number,issue_date=excluded.issue_date,due_date=excluded.due_date,subtotal_minor=excluded.subtotal_minor,tax_minor=excluded.tax_minor,total_minor=excluded.total_minor,category_id=excluded.category_id,linked_request_id=excluded.linked_request_id,corrects_event_id=excluded.corrects_event_id,notes=excluded.notes; for item in select * from jsonb_array_elements(coalesce(p_data->'items','[]')) loop insert into public.bill_items(project_id,bill_id,description,quantity,unit_price_minor,tax_minor,discount_minor,line_total_minor) values(p_project,id,item->>'description',(item->>'quantity')::numeric,(item->>'unit_price_minor')::bigint,coalesce((item->>'tax_minor')::bigint,0),coalesce((item->>'discount_minor')::bigint,0),round((item->>'quantity')::numeric*(item->>'unit_price_minor')::bigint)::bigint+coalesce((item->>'tax_minor')::bigint,0)-coalesce((item->>'discount_minor')::bigint,0)); end loop; if jsonb_array_length(coalesce(p_data->'items','[]'))>0 and n<>(select sum(line_total_minor) from public.bill_items where bill_id=save_record.id) then raise exception 'BILL_ITEMS_MISMATCH'; end if;
when 'purchase_requests' then insert into public.purchase_requests(id,project_id,requester_user_id,title,reason,estimated_minor,category_id,currency,preferred_vendor_id,desired_by_date) values(id,p_project,who,p_data->>'title',p_data->>'reason',(p_data->>'estimated_minor')::bigint,(p_data->>'category_id')::uuid,c,(p_data->>'vendor_id')::uuid,(p_data->>'desired_by_date')::date) on conflict on constraint purchase_requests_pkey do update set title=excluded.title,reason=excluded.reason,estimated_minor=excluded.estimated_minor,category_id=excluded.category_id,preferred_vendor_id=excluded.preferred_vendor_id,desired_by_date=excluded.desired_by_date; for item in select * from jsonb_array_elements(coalesce(p_data->'items','[]')) loop insert into public.purchase_request_items(project_id,request_id,description,quantity,estimated_unit_minor,estimated_total_minor) values(p_project,id,item->>'description',(item->>'quantity')::numeric,(item->>'unit_price_minor')::bigint,round((item->>'quantity')::numeric*(item->>'unit_price_minor')::bigint)); end loop;
when 'advances' then source:=coalesce((p_data->>'member_user_id')::uuid,who); if source<>who then perform private.assert_finance(p_project); end if; if not exists(select 1 from public.project_members where project_id=p_project and user_id=source and is_active) then raise exception 'INVALID_MEMBER'; end if; insert into public.advances(id,project_id,member_user_id,requested_minor,currency,purpose,created_by) values(id,p_project,source,coalesce((p_data->>'requested_minor')::bigint,(p_data->>'total_minor')::bigint,0),c,p_data->>'purpose',who) on conflict on constraint advances_pkey do update set requested_minor=excluded.requested_minor,purpose=excluded.purpose;
when 'reimbursement_claims' then source:=coalesce((p_data->>'member_user_id')::uuid,who); if source<>who then perform private.assert_finance(p_project); end if; for item in select * from jsonb_array_elements(p_data->'items') loop perform 1 from public.purchase_funding_allocations f join public.purchases p on p.id=f.purchase_id where f.id=(item->>'allocation_id')::uuid and f.project_id=p_project and f.source_type='MEMBER' and f.member_user_id=source and p.status='posted' for update of f; if not found then raise exception 'INVALID_ENTITLEMENT'; end if; n:=(item->>'amount_minor')::bigint; if n<=0 or n>private.source_outstanding((item->>'allocation_id')::uuid)-coalesce((select sum(ci.claimed_minor) from public.reimbursement_claim_items ci join public.reimbursement_claims cl on cl.id=ci.reimbursement_claim_id where ci.purchase_funding_allocation_id=(item->>'allocation_id')::uuid and cl.status not in ('rejected','voided','paid')),0) then raise exception 'ENTITLEMENT_RESERVED'; end if; sum_claim:=sum_claim+n; end loop; insert into public.reimbursement_claims(id,project_id,claimant_user_id,requested_minor,currency,notes) values(id,p_project,source,sum_claim,c,p_data->>'notes'); for item in select * from jsonb_array_elements(p_data->'items') loop insert into public.reimbursement_claim_items(project_id,reimbursement_claim_id,purchase_funding_allocation_id,claimed_minor) values(p_project,id,(item->>'allocation_id')::uuid,(item->>'amount_minor')::bigint); end loop;
when 'budget_lines' then insert into public.budget_lines(id,project_id,budget_id,category_id,planned_minor,warning_percent,hard_stop) values(id,p_project,(p_data->>'budget_id')::uuid,(p_data->>'category_id')::uuid,(p_data->>'planned_minor')::bigint,coalesce((p_data->>'warning_percent')::integer,80),coalesce((p_data->>'hard_stop')::boolean,false));
when 'budgets' then insert into public.budgets(id,project_id,name,start_date,end_date) values(id,p_project,p_data->>'name',(p_data->>'start_date')::date,(p_data->>'end_date')::date); for item in select * from jsonb_array_elements(p_data->'lines') loop insert into public.budget_lines(project_id,budget_id,category_id,planned_minor,warning_percent,hard_stop) values(p_project,id,(item->>'category_id')::uuid,(item->>'planned_minor')::bigint,coalesce((item->>'warning_percent')::integer,80),coalesce((item->>'hard_stop')::boolean,false)); end loop;
when 'approval_policies' then if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; if p_data->>'entity_type' not in ('purchases','bills','reimbursement_claims','purchase_requests','advances') or jsonb_array_length(p_data->'rule_json'->'steps')<1 then raise exception 'INVALID_POLICY'; end if; insert into public.approval_policies(id,project_id,name,entity_type,priority,rule_json) values(id,p_project,p_data->>'name',p_data->>'entity_type',coalesce((p_data->>'priority')::integer,0),p_data->'rule_json');
when 'assets' then insert into public.assets(id,project_id,name,serial_number,asset_tag,currency,purchase_value_minor,location,notes) values(id,p_project,p_data->>'name',p_data->>'serial_number',p_data->>'asset_tag',c,coalesce((p_data->>'purchase_value_minor')::bigint,0),p_data->>'location',p_data->>'notes');
when 'recurring_expense_templates' then insert into public.recurring_expense_templates(id,project_id,description,amount_minor,currency,recurrence_rule,next_due_date,vendor_id,category_id) values(id,p_project,p_data->>'description',(p_data->>'amount_minor')::bigint,c,p_data->>'recurrence_rule',(p_data->>'next_due_date')::date,(p_data->>'vendor_id')::uuid,(p_data->>'category_id')::uuid);
when 'document_templates' then insert into public.document_templates(id,project_id,template_type,name,subject_template,body_template,created_by) values(id,p_project,'custom',p_data->>'name',p_data->>'subject_template',p_data->>'body_template',who);
when 'comments' then perform private.validate_entity(p_project,p_data->>'entity_type',(p_data->>'entity_id')::uuid); insert into public.comments(id,project_id,entity_type,entity_id,author_user_id,body) values(id,p_project,p_data->>'entity_type',(p_data->>'entity_id')::uuid,who,p_data->>'body');
else raise exception 'INVALID_RECORD_TYPE'; end case;
perform private.log(p_project,p_table||'_created',p_table,id); return id; end $$;
create function private.validate_entity(p uuid,t text,e uuid) returns void language plpgsql set search_path='' as $$ declare found boolean; begin if t='projects' then found:=e=p; elsif t in ('purchases','bills','advances','reimbursement_claims','purchase_requests','assets','financial_events','generated_documents') then execute format('select exists(select 1 from public.%I where id=$1 and project_id=$2)',t) into found using e,p; else raise exception 'INVALID_ENTITY'; end if; if not found then raise exception 'ENTITY_PROJECT_MISMATCH'; end if; end $$;
create function public.submit_approval(p_project uuid,p_table text,p_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare pol public.approval_policies; rec jsonb; i uuid; s jsonb; ord integer:=0; n bigint; owner_id uuid; begin
if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) or p_table not in ('purchases','bills','advances','purchase_requests','reimbursement_claims') then raise exception 'PERMISSION_DENIED'; end if;
perform 1 from public.projects where id=p_project for update;
execute format('select to_jsonb(t) from public.%I t where id=$1 and project_id=$2 for update',p_table) into rec using p_id,p_project;
if rec is null or rec->>'status' not in ('draft','needs_info') then raise exception 'NOT_SUBMITTABLE'; end if;
owner_id:=coalesce((rec->>'created_by')::uuid,(rec->>'requester_user_id')::uuid,(rec->>'claimant_user_id')::uuid);
if owner_id<>auth.uid() and not private.finance(p_project) then raise exception 'PERMISSION_DENIED'; end if;
n:=coalesce((rec->>'total_minor')::bigint,(rec->>'estimated_minor')::bigint,(rec->>'requested_minor')::bigint,0);
select * into pol from public.approval_policies where project_id=p_project and entity_type=p_table and is_active and coalesce((rule_json->>'minimum_minor')::bigint,0)<=n and (rule_json->>'category_id' is null or rule_json->>'category_id'=rec->>'category_id') order by priority desc limit 1;
insert into public.approval_instances(project_id,entity_type,entity_id,policy_id,approved_amount_minor,status,completed_at) values(p_project,p_table,p_id,pol.id,n,case when pol.id is null then 'approved' else 'pending' end,case when pol.id is null then now() else null end) returning id into i;
if pol.id is not null then for s in select * from jsonb_array_elements(pol.rule_json->'steps') loop ord:=ord+1; if not exists(select 1 from public.project_members where project_id=p_project and is_active and user_id<>owner_id and ((s->>'user_id' is not null and user_id=(s->>'user_id')::uuid) or (s->>'role' is not null and role=(s->>'role')::public.project_role))) then raise exception 'NO_ELIGIBLE_APPROVER'; end if; insert into public.approval_steps(project_id,approval_instance_id,step_order,approver_user_id,approver_role) values(p_project,i,ord,(s->>'user_id')::uuid,(s->>'role')::public.project_role); end loop; end if;
execute format('update public.%I set status=$1 where id=$2',p_table) using case when pol.id is null then 'approved' else 'submitted' end,p_id;
if p_table='reimbursement_claims' and pol.id is null then update public.reimbursement_claims set approved_minor=requested_minor,approved_at=now() where id=p_id; end if;
perform private.log(p_project,'approval_submitted',p_table,p_id); return i;
end $$;
create function public.decide_approval(p_step uuid,p_decision text,p_comment text default '') returns void language plpgsql security definer set search_path='' as $$ declare s public.approval_steps; inst public.approval_instances; rec jsonb; owner_id uuid; begin
select * into s from public.approval_steps where id=p_step for update; select * into inst from public.approval_instances where id=s.approval_instance_id for update;
if s.id is null or inst.status<>'pending' or s.status<>'pending' or p_decision not in ('approved','rejected','needs_info') or not private.member(s.project_id) or not(coalesce(s.approver_user_id=auth.uid(),false) or private.role(s.project_id,array[s.approver_role])) then raise exception 'PERMISSION_DENIED'; end if;
if exists(select 1 from public.approval_steps where approval_instance_id=inst.id and step_order<s.step_order and status<>'approved') then raise exception 'PREVIOUS_APPROVAL_REQUIRED'; end if;
execute format('select to_jsonb(t) from public.%I t where id=$1',inst.entity_type) into rec using inst.entity_id;
owner_id:=coalesce((rec->>'created_by')::uuid,(rec->>'requester_user_id')::uuid,(rec->>'claimant_user_id')::uuid); if owner_id=auth.uid() then raise exception 'SELF_APPROVAL_FORBIDDEN'; end if;
update public.approval_steps set status=p_decision,decided_by=auth.uid(),decided_at=now(),comment=p_comment where id=p_step;
if p_decision<>'approved' or not exists(select 1 from public.approval_steps where approval_instance_id=inst.id and status<>'approved') then update public.approval_instances set status=p_decision,completed_at=now() where id=inst.id; execute format('update public.%I set status=$1 where id=$2',inst.entity_type) using p_decision,inst.entity_id; if p_decision='approved' and inst.entity_type='reimbursement_claims' then update public.reimbursement_claims set approved_minor=requested_minor,approved_at=now() where id=inst.entity_id; end if; end if;
perform private.log(s.project_id,'approval_'||p_decision,inst.entity_type,inst.entity_id,p_comment); end $$;
create function public.project_summary(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare cash bigint; expense bigint; payable bigint; bills bigint; advances bigint; funding bigint; reserved bigint; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if;
select coalesce(sum(case when a.account_type in ('CASH','BANK','WALLET') then case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end else 0 end),0),coalesce(sum(case when a.account_type='EXPENSE' then case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end else 0 end),0),coalesce(sum(case when a.account_type='MEMBER_PAYABLE' then case l.direction when 'CREDIT' then l.amount_minor else -l.amount_minor end else 0 end),0),coalesce(sum(case when a.account_type='VENDOR_PAYABLE' then case l.direction when 'CREDIT' then l.amount_minor else -l.amount_minor end else 0 end),0),coalesce(sum(case when a.account_type='ADVANCE' then case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end else 0 end),0),coalesce(sum(case when a.account_type in ('FUNDING','EXTERNAL') then case l.direction when 'CREDIT' then l.amount_minor else -l.amount_minor end else 0 end),0) into cash,expense,payable,bills,advances,funding from public.ledger_entries l join public.financial_accounts a on a.id=l.account_id where l.project_id=p_project;
select coalesce(sum(private.request_remaining(r.id)),0) into reserved from public.purchase_requests r where r.project_id=p_project and r.status='approved';
return jsonb_build_object('cash',cash::text,'expense',expense::text,'payable',payable::text,'bills',bills::text,'advances',advances::text,'funding',funding::text,'reserved',reserved::text,'available',(cash-payable-bills-reserved)::text); end $$;
create function public.project_records(p_project uuid,p_table text,p_limit integer default 50,p_offset integer default 0,p_search text default '',p_order text default 'id',p_desc boolean default false,p_filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$ declare rows jsonb; total bigint; predicate text; begin
if not private.member(p_project) or p_table not in ('purchases','purchase_items','purchase_funding_allocations','bills','bill_payments','reimbursement_claims','reimbursement_claim_items','reimbursement_payments','advances','advance_returns','purchase_requests','vendors','assets','documents','generated_documents','budgets','budget_lines','categories','financial_accounts','funding_sources','financial_events','ledger_entries','activity_events','audit_logs','project_members','approval_steps','approval_instances','approval_policies','comments','recurring_expense_templates','tags','funding_tranches','refunds') then raise exception 'PERMISSION_DENIED'; end if;
if p_table='audit_logs' then perform private.assert_finance(p_project); end if;
if not exists(select 1 from information_schema.columns where table_schema='public' and table_name=p_table and column_name=p_order) then raise exception 'INVALID_SORT'; end if;
predicate:='project_id=$1 and ($2='''' or to_jsonb(t)::text ilike ''%''||$2||''%'') and (coalesce($3->>''status'','''')='''' or to_jsonb(t)->>''status''=$3->>''status'') and (coalesce($3->>''from'','''')='''' or coalesce(to_jsonb(t)->>''purchase_date'',to_jsonb(t)->>''event_date'',to_jsonb(t)->>''issue_date'',to_jsonb(t)->>''created_at'')::date>=nullif($3->>''from'','''')::date) and (coalesce($3->>''to'','''')='''' or coalesce(to_jsonb(t)->>''purchase_date'',to_jsonb(t)->>''event_date'',to_jsonb(t)->>''issue_date'',to_jsonb(t)->>''created_at'')::date<=nullif($3->>''to'','''')::date)';
-- bigint values are serialized as strings before reaching JavaScript.
execute format('select count(*) from public.%I t where %s',p_table,predicate) into total using p_project,p_search,p_filters;
execute format($records$select coalesce(jsonb_agg(private.safe_json(to_jsonb(t))||case when $6='purchases' then jsonb_build_object('item_summary',(select string_agg(pi.description,', ') from public.purchase_items pi where pi.purchase_id=(to_jsonb(t)->>'id')::uuid)) else '{}'::jsonb end),'[]') from (select * from public.%I t where %s order by %I %s,id limit $4 offset $5) t$records$,p_table,predicate,p_order,case when p_desc then 'desc' else 'asc' end) into rows using p_project,p_search,p_filters,least(greatest(p_limit,1),200),greatest(p_offset,0),p_table;
return jsonb_build_object('rows',rows,'total',total); end $$;
create function private.safe_json(j jsonb) returns jsonb language plpgsql immutable set search_path='' as $$ declare k text; v jsonb; r jsonb:='{}'; begin for k,v in select * from jsonb_each(j) loop if k like '%_minor' then r:=r||jsonb_build_object(k,case when v='null'::jsonb then null else v#>>'{}' end); else r:=r||jsonb_build_object(k,v); end if; end loop; return r; end $$;
create function public.close_project(p_project uuid,p_reason text default null) returns void language plpgsql security definer set search_path='' as $$ declare s jsonb; begin if not private.role(p_project,array['OWNER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform 1 from public.projects where id=p_project for update; s:=public.project_summary(p_project); if (s->>'payable')::bigint<>0 or (s->>'bills')::bigint<>0 or (s->>'advances')::bigint<>0 or (s->>'reserved')::bigint<>0 or exists(select 1 from public.approval_instances where project_id=p_project and status='pending') then raise exception 'UNSETTLED_PROJECT'; end if; update public.projects set status='closed',closed_at=now() where id=p_project; perform private.log(p_project,'project_closed','projects',p_project,p_reason); end $$;
revoke execute on all functions in schema public from public;
grant execute on all functions in schema public to authenticated;
revoke execute on all functions in schema private from public;
grant execute on function private.member(uuid),private.role(uuid,public.project_role[]),private.finance(uuid) to authenticated;
